/* مرصاد -> سير عملك.
   يوحّد ما يصل من الموقع: الحقول مسطّحة في الأعلى وبأسماء عربية أيضًا،
   والملفات ممرّرة كما وصلت وبالاسمين العامّين data و file — فتجدها
   عقدتك مهما كان الاسم الذي تنتظره، بلا أن تعدّل فيها شيئًا. */

const item = $input.first();
const body = (item.json && item.json.body) || item.json || {};
const bin  = item.binary || {};

const fields = {
  structure: body.structure || '',
  notes:     body.notes     || '',
  date:      body.date      || '',
  type:      body.type      || '',
  engineer:  body.engineer  || '',
  section:   body.section   || '',
};

const arabic = {
  'المنشأة':         fields.structure,
  'الملاحظات':       fields.notes,
  'التاريخ':          fields.date,
  'نوع الفحص':       fields.type,
  'الموظف المسؤول': fields.engineer,
  'القطاع':          fields.section,
};

/* الملفات: file0, file1 … كما وصلت، ومعها data و file للعقد التي تنتظر
   الاسم العام. النسخ هنا مرجعيّ لا يضاعف الحجم. */
const names = Object.keys(bin);
const out = Object.assign({}, bin);
if (names.length) { out.data = bin[names[0]]; out.file = bin[names[0]]; }

return [{
  json: Object.assign({}, fields, arabic, {
    fileCount: names.length,
    fileNames: names,
  }),
  binary: out,
}];

/* سير عملك -> مرصاد.
   يقبل ما تخرجه عقدتك على عِلّاته — مصفوفة ملاحظات، أو كائنًا فيه
   findings، أو نصّ نموذج لغوي فيه JSON — ويردّه بالصيغة الموثّقة.
   فلا يلزمك أن تعيد تشكيل مخرجات وكيلك. */

const items = $input.all();
let findings = [];

for (const it of items) {
  const j = it.json || {};

  if (Array.isArray(j.findings)) { findings = findings.concat(j.findings); continue; }
  if (Array.isArray(j.results))  { findings = findings.concat(j.results);  continue; }
  if (Array.isArray(j.output))   { findings = findings.concat(j.output);   continue; }
  if (j.title || j.label || j.name || j.finding) { findings.push(j); continue; }

  /* نموذج لغوي ردّ بنصّ، وربما حول JSON */
  const text = ['text', 'output', 'content', 'message', 'response', 'data']
    .map(k => (typeof j[k] === 'string' ? j[k] : ''))
    .find(Boolean) || '';
  const m = text.match(/[[{][\s\S]*[\]}]/);
  if (m) {
    try {
      const p = JSON.parse(m[0]);
      findings = findings.concat(Array.isArray(p) ? p : (p.findings || p.results || [p]));
    } catch (e) { /* ليس JSON بعد كل شيء */ }
  } else if (text.trim()) {
    findings.push({ title: text.trim().slice(0, 120), severity: 'medium' });
  }
}

findings = findings.filter(f => f && (f.title || f.label || f.name || f.note));

if (!findings.length) {
  findings = [{
    title: 'الوصل يعمل — لم تصل ملاحظات بعد',
    titleEn: 'Connection works — no findings yet',
    severity: 'medium',
    note: 'عقدة «صُغ الجواب» لم تجد ملاحظات فيما وصلها. ضع عقد وكيلك قبلها.',
  }];
}

const scored = findings.map(f => Number(f.confidence)).filter(n => !isNaN(n));
const accuracy = scored.length
  ? Math.round(scored.reduce((a, b) => a + b, 0) / scored.length)
  : null;

return [{ json: accuracy === null ? { findings } : { accuracy, findings } }];
